/** Native movable overlay for the ordinary task work timer, independent from Pomodoro. */
public final class AdibWorkTimerOverlayService extends Service {
    static final String ACTION_SYNC="com.adib.maintenance.WORK_TIMER_SYNC",ACTION_REFRESH="com.adib.maintenance.WORK_TIMER_REFRESH",ACTION_STOP="com.adib.maintenance.WORK_TIMER_STOP",ACTION_HIDE="com.adib.maintenance.WORK_TIMER_HIDE",ACTION_TOGGLE="com.adib.maintenance.WORK_TIMER_TOGGLE",ACTION_PENDING="com.adib.maintenance.WORK_TIMER_PENDING";
    static final String PREFS="adib_work_timer";static final String BROADCAST_PENDING="com.adib.maintenance.WORK_TIMER_PENDING_EVENT";
    private static final String CHANNEL="adib_work_timer",PENDING_KEY="pending_session";private static final int NOTIFICATION_ID=4128;
    private static final ExecutorService IO=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler();private WindowManager wm;private View overlay;private WindowManager.LayoutParams params;private TextView title,clock,stopButton;
    private String sessionId="",taskId="",taskTitle="Tapşırıq",worker="",sourceKey="todo",sessionJson="";private int revision=0;private long startedAt=0,baseSeconds=0,startUptime=0;private boolean running=false,mini=false,stopping=false,confirming=false,saving=false;private long endedAt=0;private EditText startField,endField;private TextView confirmationError,saveButton;
    private final Runnable ticker=new Runnable(){@Override public void run(){if(running){updateClock();updateNotification();handler.postDelayed(this,1000);}}};
    static void sync(Context c,JSONObject session,long serverNow){Intent i=new Intent(c,AdibWorkTimerOverlayService.class).setAction(ACTION_SYNC).putExtra("session",session==null?"{}":session.toString()).putExtra("serverNow",serverNow);start(c,i);}
    static void refresh(Context c){Intent i=new Intent(c,AdibWorkTimerOverlayService.class).setAction(ACTION_REFRESH);start(c,i);}
    static void stop(Context c){Intent i=new Intent(c,AdibWorkTimerOverlayService.class).setAction(ACTION_STOP);start(c,i);}
    private static void start(Context c,Intent i){try{if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}catch(RuntimeException e){android.util.Log.w("ADIB","Work timer overlay could not start",e);}}
    @Override public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);createChannel();}
    @Override public int onStartCommand(Intent in,int flags,int startId){String action=in==null?ACTION_REFRESH:in.getAction();
        if(ACTION_SYNC.equals(action)&&in!=null)readSession(in.getStringExtra("session"),in.getLongExtra("serverNow",System.currentTimeMillis()));else load();
        if(running||confirming)startForeground(NOTIFICATION_ID,notification());
        if(ACTION_STOP.equals(action)){stopCurrent();return START_NOT_STICKY;}
        if(ACTION_HIDE.equals(action)){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",true).apply();removeOverlay();if(running||confirming)startForeground(NOTIFICATION_ID,notification());else stopSelf();return START_NOT_STICKY;}
        if(ACTION_TOGGLE.equals(action)&&!confirming){mini=!mini;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("mini",mini).apply();showOverlay();}
        if(ACTION_REFRESH.equals(action)){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",false).apply();}
        if(!running&&!confirming){removeOverlay();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY;}
        if(startUptime==0)startUptime=SystemClock.elapsedRealtime();startForeground(NOTIFICATION_ID,notification());
        if(!getSharedPreferences(PREFS,MODE_PRIVATE).getBoolean("hidden",false))showOverlay();handler.removeCallbacks(ticker);if(running)ticker.run();return START_STICKY;
    }
    private void readSession(String raw,long serverNow){try{JSONObject s=new JSONObject(raw);if(s.optString("id").equals(sessionId)&&s.optInt("revision",0)<revision)return;sessionJson=s.toString();sessionId=s.optString("id","");taskId=s.optString("taskId","");taskTitle=s.optString("title","Tapşırıq");worker=s.optString("worker","");sourceKey=s.optString("sourceKey","todo");revision=s.optInt("revision",0);startedAt=s.optLong("startedAt",serverNow);running="running".equals(s.optString("status"));confirming="pending".equals(s.optString("status"));endedAt=s.optLong("endedAt",0);baseSeconds=running?Math.max(0,(serverNow-startedAt)/1000):Math.max(0,s.optLong("seconds",0));startUptime=SystemClock.elapsedRealtime();mini=getSharedPreferences(PREFS,MODE_PRIVATE).getBoolean("mini",false);persist();if("pending".equals(s.optString("status")))getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString(PENDING_KEY,s.toString()).apply();else if("saved".equals(s.optString("status")))getSharedPreferences(PREFS,MODE_PRIVATE).edit().remove(PENDING_KEY).apply();}catch(Exception e){android.util.Log.w("ADIB","Invalid work timer session",e);}}
    private void load(){android.content.SharedPreferences p=getSharedPreferences(PREFS,MODE_PRIVATE);sessionJson=p.getString("sessionJson","");sessionId=p.getString("sessionId","");taskId=p.getString("taskId","");taskTitle=p.getString("title","Tapşırıq");worker=p.getString("worker","");sourceKey=p.getString("sourceKey","todo");revision=p.getInt("revision",0);startedAt=p.getLong("startedAt",0);baseSeconds=p.getLong("baseSeconds",0);startUptime=p.getLong("startUptime",0);running=p.getBoolean("running",false);mini=p.getBoolean("mini",false);try{JSONObject session=new JSONObject(sessionJson);confirming="pending".equals(session.optString("status"));endedAt=session.optLong("endedAt",0);}catch(Exception ignored){confirming=false;}}
    private void persist(){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString("sessionJson",sessionJson).putString("sessionId",sessionId).putString("taskId",taskId).putString("title",taskTitle).putString("worker",worker).putString("sourceKey",sourceKey).putInt("revision",revision).putLong("startedAt",startedAt).putLong("baseSeconds",baseSeconds).putLong("startUptime",startUptime).putBoolean("running",running).apply();}
    long elapsed(){return baseSeconds+(running?Math.max(0,(SystemClock.elapsedRealtime()-startUptime)/1000):0);}
    private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=getSystemService(NotificationManager.class);if(nm!=null){NotificationChannel c=new NotificationChannel(CHANNEL,"Рабочий таймер ADIB",NotificationManager.IMPORTANCE_LOW);c.setDescription("Активный таймер работы по задаче");nm.createNotificationChannel(c);}}}
    private Notification notification(){Intent open=confirming?new Intent(this,AdibWorkTimerOverlayService.class).setAction(ACTION_REFRESH):new Intent(this,OnlineMainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=confirming?PendingIntent.getService(this,4128,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE):PendingIntent.getActivity(this,4128,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setSmallIcon(R.drawable.ic_adib).setContentTitle(confirming?"ADIB · Подтвердите рабочее время":"ADIB · Рабочий таймер").setContentText(taskTitle+" · "+format(elapsed())).setContentIntent(pi).setOngoing(true).setShowWhen(false).build();}
    private void updateNotification(){NotificationManager nm=getSystemService(NotificationManager.class);if(nm!=null)nm.notify(NOTIFICATION_ID,notification());}
    private String format(long s){s=Math.max(0,s);return String.format(Locale.getDefault(),"%02d:%02d:%02d",s/3600,(s/60)%60,s%60);}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable surface(){GradientDrawable d=new GradientDrawable();d.setColor(HybridUi.surface(true));d.setCornerRadius(dp(18));d.setStroke(dp(1),HybridUi.border(true));return d;}
    private TextView actionButton(String label){TextView b=new TextView(this);b.setText(label);b.setTextColor(HybridUi.text(true));b.setTextSize(15);b.setGravity(Gravity.CENTER);b.setContentDescription(label);return b;}
    private void showOverlay(){if(!Settings.canDrawOverlays(this)){removeOverlay();return;}if(confirming){showConfirmation();return;}int oldX=params==null?0:params.x,oldY=params==null?dp(58):params.y;removeOverlay();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.HORIZONTAL);box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(8),dp(5),dp(7),dp(5));box.setBackground(surface());box.setElevation(dp(10));
        if(!mini){TextView grip=actionButton("⠿");grip.setTextColor(HybridUi.muted(true));box.addView(grip,new LinearLayout.LayoutParams(dp(24),dp(44)));LinearLayout texts=new LinearLayout(this);texts.setOrientation(LinearLayout.VERTICAL);texts.setPadding(dp(4),0,dp(5),0);box.addView(texts,new LinearLayout.LayoutParams(0,-2,1));title=new TextView(this);title.setText(taskTitle+(worker.isEmpty()?"":" · "+worker));title.setTextColor(HybridUi.text(true));title.setTextSize(10);title.setMaxLines(1);title.setTypeface(null,Typeface.BOLD);texts.addView(title);clock=new TextView(this);clock.setTextColor(HybridUi.accent(true));clock.setTextSize(18);clock.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);texts.addView(clock);stopButton=actionButton("■");stopButton.setContentDescription("Остановить рабочий таймер");box.addView(stopButton,new LinearLayout.LayoutParams(dp(42),dp(44)));stopButton.setOnClickListener(v->{if(!stopping){stopping=true;stopButton.setText("…");stopCurrent();}});TextView collapse=actionButton("−");collapse.setContentDescription("Свернуть таймер до времени");box.addView(collapse,new LinearLayout.LayoutParams(dp(32),dp(44)));collapse.setOnClickListener(v->toggleMini());TextView hide=actionButton("×");hide.setTextSize(20);hide.setContentDescription("Скрыть окно, оставив таймер работающим");box.addView(hide,new LinearLayout.LayoutParams(dp(28),dp(44)));hide.setOnClickListener(v->{getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",true).apply();removeOverlay();});drag(box,grip);
        }else{clock=actionButton(format(elapsed()));clock.setTextColor(HybridUi.accent(true));clock.setTextSize(16);clock.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);clock.setContentDescription("Рабочий таймер. Нажмите, чтобы развернуть");box.addView(clock,new LinearLayout.LayoutParams(-1,dp(42)));box.setOnClickListener(v->toggleMini());drag(box,clock);}
        params=new WindowManager.LayoutParams(dp(mini?132:320),dp(mini?52:58),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.x=oldX;params.y=oldY;overlay=box;try{wm.addView(box,params);getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",false).apply();updateClock();}catch(Exception e){overlay=null;android.widget.Toast.makeText(this,"Не удалось открыть рабочий таймер поверх приложений. Проверьте разрешение ADIB.",android.widget.Toast.LENGTH_LONG).show();}}
    private void drag(View target,View dragHandle){dragHandle.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;boolean moved;final int slop=android.view.ViewConfiguration.get(AdibWorkTimerOverlayService.this).getScaledTouchSlop();@Override public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:sx=e.getRawX();sy=e.getRawY();ox=params.x;oy=params.y;moved=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.hypot(dx,dy)>slop)moved=true;if(moved){params.x=ox+(int)dx;params.y=Math.max(0,oy+(int)dy);try{wm.updateViewLayout(target,params);}catch(Exception ignored){}}return true;case MotionEvent.ACTION_UP:if(mini&&!moved)target.performClick();return true;case MotionEvent.ACTION_CANCEL:return true;default:return true;}}});}
    private void toggleMini(){if(confirming){showConfirmation();return;}mini=!mini;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("mini",mini).apply();showOverlay();}
    private void updateClock(){if(clock!=null)clock.setText(format(elapsed()));}
    private void removeOverlay(){if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;}clock=null;title=null;stopButton=null;startField=null;endField=null;confirmationError=null;saveButton=null;}
    private void stopCurrent(){if(confirming){showConfirmation();return;}if(!running||sessionId.isEmpty()){removeOverlay();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return;}stopping=true;if(stopButton!=null)stopButton.setText("…");String sid=sessionId;int rev=revision;IO.execute(()->{try{JSONObject body=new JSONObject().put("action","stop").put("sessionId",sid).put("revision",rev).put("operationId",UUID.randomUUID().toString());JSONObject result=WorkTimerApi.action(this,body),session=result.optJSONObject("session");if(session==null)throw new IllegalStateException("Ответ сервера не содержит сеанс");handler.post(()->acceptStopped(session,result.optLong("serverNow",System.currentTimeMillis())));}catch(Exception e){try{JSONObject state=WorkTimerApi.getState(this);org.json.JSONArray own=state.optJSONArray("own");if(own!=null)for(int i=0;i<own.length();i++){JSONObject session=own.optJSONObject(i);if(session!=null&&sid.equals(session.optString("id"))&&"pending".equals(session.optString("status"))){handler.post(()->acceptStopped(session,state.optLong("serverNow",System.currentTimeMillis())));return;}}}catch(Exception ignored){}handler.post(()->{stopping=false;if(stopButton!=null)stopButton.setText("■");android.widget.Toast.makeText(this,"Не удалось остановить таймер: "+e.getMessage(),android.widget.Toast.LENGTH_LONG).show();});}});}
    private void acceptStopped(JSONObject session,long serverNow){readSession(session.toString(),serverNow);stopping=false;handler.removeCallbacks(ticker);getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("running",false).putBoolean("pending_native_confirmation",true).putBoolean("hidden",false).apply();startForeground(NOTIFICATION_ID,notification());showConfirmation();sendBroadcast(new Intent(BROADCAST_PENDING).setPackage(getPackageName()).putExtra("session",session.toString()));}
    private void showConfirmation(){if(!Settings.canDrawOverlays(this))return;if(overlay!=null&&startField!=null){updateNotification();return;}int oldX=params==null?0:params.x,oldY=params==null?dp(58):params.y;LinearLayout box;if(overlay instanceof LinearLayout){box=(LinearLayout)overlay;box.removeAllViews();}else{removeOverlay();box=new LinearLayout(this);overlay=box;}mini=false;box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.TOP);box.setPadding(dp(14),dp(10),dp(14),dp(12));box.setBackground(surface());box.setElevation(dp(10));box.setFocusableInTouchMode(true);clock=null;title=null;stopButton=null;
        TextView head=actionButton("⠿  Подтвердите рабочее время");head.setTypeface(null,Typeface.BOLD);head.setTextSize(14);box.addView(head,new LinearLayout.LayoutParams(-1,dp(38)));drag(box,head);TextView name=actionButton(taskTitle+(worker.isEmpty()?"":" · "+worker));name.setTextSize(12);name.setMaxLines(2);box.addView(name,new LinearLayout.LayoutParams(-1,-2));
        startField=confirmationField(box,"Начало",startedAt,"draft_start:");endField=confirmationField(box,"Окончание",endedAt,"draft_end:");TextView hint=actionButton("Формат: дд.ММ.гггг чч:мм:сс");hint.setTextSize(10);hint.setTextColor(HybridUi.muted(true));box.addView(hint,new LinearLayout.LayoutParams(-1,dp(28)));confirmationError=actionButton("");confirmationError.setTextColor(Color.rgb(230,112,112));confirmationError.setTextSize(12);confirmationError.setVisibility(View.GONE);box.addView(confirmationError,new LinearLayout.LayoutParams(-1,-2));LinearLayout actions=new LinearLayout(this);box.addView(actions,new LinearLayout.LayoutParams(-1,dp(44)));TextView later=actionButton("Позже");actions.addView(later,new LinearLayout.LayoutParams(0,-1,1));later.setOnClickListener(v->{if(saving)return;getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",true).apply();removeOverlay();updateNotification();});saveButton=actionButton("Подтвердить время");saveButton.setTextColor(HybridUi.accent(true));actions.addView(saveButton,new LinearLayout.LayoutParams(0,-1,2));saveButton.setOnClickListener(v->saveConfirmedTime());
        boolean attached=params!=null&&box.getParent()!=null;int width=Math.min(dp(360),getResources().getDisplayMetrics().widthPixels-dp(16));if(params==null)params=new WindowManager.LayoutParams();params.width=width;params.height=WindowManager.LayoutParams.WRAP_CONTENT;params.type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;params.flags=WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN;params.format=PixelFormat.TRANSLUCENT;params.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN;params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.x=oldX;params.y=Math.max(dp(24),Math.min(oldY,getResources().getDisplayMetrics().heightPixels-dp(380)));try{if(attached)wm.updateViewLayout(box,params);else wm.addView(box,params);box.requestFocus();getSharedPreferences(PREFS,MODE_PRIVATE).edit().putBoolean("hidden",false).apply();}catch(Exception e){removeOverlay();android.widget.Toast.makeText(this,"Не удалось открыть подтверждение: "+e.getMessage(),android.widget.Toast.LENGTH_LONG).show();}}
    private EditText confirmationField(LinearLayout box,String label,long value,String prefix){TextView text=actionButton(label);text.setTextSize(12);text.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);box.addView(text,new LinearLayout.LayoutParams(-1,dp(24)));EditText field=new EditText(this);field.setSingleLine(true);field.setTextColor(HybridUi.text(true));field.setTextSize(14);field.setTypeface(Typeface.MONOSPACE);field.setInputType(InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_NORMAL);field.setContentDescription(label+" рабочего сеанса");String key=prefix+sessionId;field.setText(getSharedPreferences(PREFS,MODE_PRIVATE).getString(key,WorkTimeEdit.format(value)));field.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){getSharedPreferences(PREFS,MODE_PRIVATE).edit().putString(key,s.toString()).apply();}public void afterTextChanged(android.text.Editable s){}});box.addView(field,new LinearLayout.LayoutParams(-1,dp(48)));return field;}
    private void saveConfirmedTime(){if(saving||!confirming||startField==null||endField==null)return;final long start,end;try{start=WorkTimeEdit.editedMillis(startField.getText().toString(),startedAt);end=WorkTimeEdit.editedMillis(endField.getText().toString(),endedAt);WorkTimeEdit.validate(start,end);}catch(Exception e){showConfirmationError(e.getMessage());return;}saving=true;saveButton.setEnabled(false);saveButton.setText("Сохраняется…");startField.setEnabled(false);endField.setEnabled(false);String sid=sessionId;int rev=revision;String key=sid+":"+rev+":"+start+":"+end;android.content.SharedPreferences preferences=getSharedPreferences(PREFS,MODE_PRIVATE);String operation=preferences.getString("save_operation_key","").equals(key)?preferences.getString("save_operation_id",""):"";if(operation.isEmpty()){operation=UUID.randomUUID().toString();preferences.edit().putString("save_operation_key",key).putString("save_operation_id",operation).apply();}String operationId=operation;IO.execute(()->{try{JSONObject result=WorkTimerApi.action(this,new JSONObject().put("action","save").put("sessionId",sid).put("revision",rev).put("startedAt",start).put("endedAt",end).put("operationId",operationId));JSONObject session=result.optJSONObject("session");if(session==null||!"saved".equals(session.optString("status")))throw new IllegalStateException("Сервер не подтвердил сохранение");handler.post(()->{readSession(session.toString(),result.optLong("serverNow",System.currentTimeMillis()));saving=false;getSharedPreferences(PREFS,MODE_PRIVATE).edit().remove(PENDING_KEY).remove("draft_start:"+sid).remove("draft_end:"+sid).remove("save_operation_key").remove("save_operation_id").putBoolean("pending_native_confirmation",false).apply();sendBroadcast(new Intent(BROADCAST_PENDING).setPackage(getPackageName()).putExtra("session",session.toString()));removeOverlay();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();android.widget.Toast.makeText(this,"Рабочее время подтверждено",android.widget.Toast.LENGTH_SHORT).show();});}catch(Exception e){handler.post(()->{saving=false;if(saveButton!=null){saveButton.setEnabled(true);saveButton.setText("Подтвердить время");}if(startField!=null)startField.setEnabled(true);if(endField!=null)endField.setEnabled(true);showConfirmationError("Не удалось сохранить: "+e.getMessage()+". Время не подтверждено.");});}});}
    private void showConfirmationError(String message){if(confirmationError!=null){confirmationError.setText(message);confirmationError.setVisibility(View.VISIBLE);}}
    private void notifyStopped(){try{Intent open=new Intent(this,OnlineMainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,4129,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);Notification n=b.setSmallIcon(R.drawable.ic_adib).setContentTitle("Рабочий таймер остановлен").setContentText(taskTitle+" · подтвердите записанное время в ADIB").setContentIntent(pi).setAutoCancel(true).build();NotificationManager nm=getSystemService(NotificationManager.class);if(nm!=null)nm.notify(4129,n);}catch(Exception ignored){}}
    @Override public void onDestroy(){handler.removeCallbacks(ticker);removeOverlay();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
    @Override public IBinder onBind(Intent intent){return null;}
}
